    private static UIElement SettlementRing(decimal ratio)
    {
        var value=(double)Math.Clamp(ratio,0,1);var ring=new Grid{Width=140,Height=140,HorizontalAlignment=HorizontalAlignment.Center};ring.Children.Add(new Ellipse{Stroke=Brush(0xFB, 0xEF, 0xDF),StrokeThickness=14});
        if(value>=1)ring.Children.Add(new Ellipse{Stroke=Green,StrokeThickness=14});
        else if(value>0){var angle=2*Math.PI*value;var figure=new PathFigure{StartPoint=new Windows.Foundation.Point(70,7)};figure.Segments.Add(new ArcSegment{Point=new Windows.Foundation.Point(70+63*Math.Sin(angle),70-63*Math.Cos(angle)),Size=new Windows.Foundation.Size(63,63),IsLargeArc=value>.5,SweepDirection=SweepDirection.Clockwise});var geometry=new PathGeometry();geometry.Figures.Add(figure);ring.Children.Add(new Microsoft.UI.Xaml.Shapes.Path{Data=geometry,Stroke=Green,StrokeThickness=14});}
        var label=Stack(1);label.HorizontalAlignment=HorizontalAlignment.Center;label.VerticalAlignment=VerticalAlignment.Center;var percent=Text(value.ToString("P0"),26,true);percent.HorizontalAlignment=HorizontalAlignment.Center;label.Children.Add(percent);var caption=Text("settled",11);caption.Foreground=Muted;caption.HorizontalAlignment=HorizontalAlignment.Center;label.Children.Add(caption);ring.Children.Add(label);Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(ring,value.ToString("P0")+" of posted invoices settled");return ring;
    }

    private UIElement MonthChart(DateTime start,DateTime end)
    {
        var rows=new List<(DateTime Month,decimal Sales,decimal Purchases)>();
        for(var m=new DateTime(start.Year,start.Month,1);m<=end&&rows.Count<13;m=m.AddMonths(1)){var key=m.ToString("yyyy-MM");var records=Records.OfType<JsonObject>().Where(r=>r.Flag("posted")&&r.Text("date").StartsWith(key)&&string.CompareOrdinal(r.Text("date"),start.ToString("yyyy-MM-dd"))>=0&&string.CompareOrdinal(r.Text("date"),end.ToString("yyyy-MM-dd"))<=0).ToArray();rows.Add((m,records.Sum(r=>r.Text("kind") is "sales_invoice" or "pos"?r.Number("amount"):r.Text("kind")=="credit_note"?-r.Number("amount"):0),records.Sum(r=>r.Text("kind")=="purchase_bill"?r.Number("amount"):r.Text("kind")=="debit_note"?-r.Number("amount"):0)));}
        var values=rows.SelectMany(r=>new[]{r.Sales,r.Purchases}).ToArray();var max=Math.Max(0,values.DefaultIfEmpty().Max());var min=Math.Min(0,values.DefaultIfEmpty().Min());var span=max-min;
        if(span==0){var empty=Text("No net movement in this period.\nPosted sales and purchases will appear here.",14);empty.Margin=new Thickness(0,50,0,50);empty.Foreground=Muted;return empty;}
        var grid=new Grid{ColumnSpacing=6};var baseline=140*(double)(max/span);
        for(var i=0;i<rows.Count;i++){grid.ColumnDefinitions.Add(new ColumnDefinition());var r=rows[i];var group=Stack(9);var canvas=new Canvas{Height=150,HorizontalAlignment=HorizontalAlignment.Stretch};var sales=new Rectangle{Fill=Green,RadiusX=3,RadiusY=3};var purchases=new Rectangle{Fill=Brush(0xEF, 0xBB, 0x8C),RadiusX=3,RadiusY=3};var axis=new Line{Stroke=Brush(0xCF, 0xD5, 0xDF),StrokeThickness=1,Y1=baseline,Y2=baseline};canvas.Children.Add(axis);canvas.Children.Add(sales);canvas.Children.Add(purchases);void Resize(){axis.X2=canvas.ActualWidth;var w=Math.Min(20,canvas.ActualWidth*.3);void Bar(Rectangle rect,decimal value,double x){var y=140*(double)((max-value)/span);rect.Width=w;rect.Height=Math.Abs(y-baseline);Canvas.SetTop(rect,Math.Min(y,baseline));Canvas.SetLeft(rect,x);}Bar(sales,r.Sales,canvas.ActualWidth/2-w-2);Bar(purchases,r.Purchases,canvas.ActualWidth/2+2);}canvas.SizeChanged+=(_,_)=>Resize();group.Children.Add(canvas);var label=Text(r.Month.ToString("MMM"),11);label.HorizontalAlignment=HorizontalAlignment.Center;label.Foreground=Muted;group.Children.Add(label);var description=$"{r.Month:MMMM yyyy}: net sales {J.Money(r.Sales)}, net purchases {J.Money(r.Purchases)}";ToolTipService.SetToolTip(group,description);Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(group,description);Grid.SetColumn(group,i);grid.Children.Add(group);}
        return grid;
    }
    private static Grid ResponsiveMetrics(params UIElement[] cards){var grid=new Grid{ColumnSpacing=18,RowSpacing=18};foreach(var card in cards)grid.Children.Add(card);var current=0;void Arrange(int count){if(current==count)return;current=count;grid.ColumnDefinitions.Clear();grid.RowDefinitions.Clear();for(var col=0;col<count;col++)grid.ColumnDefinitions.Add(new ColumnDefinition());for(var row=0;row<(cards.Length+count-1)/count;row++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});for(var i=0;i<cards.Length;i++){Grid.SetColumn((FrameworkElement)cards[i],i%count);Grid.SetRow((FrameworkElement)cards[i],i/count);}}Arrange(2);grid.SizeChanged+=(_,_)=>Arrange(grid.ActualWidth>=720?4:grid.ActualWidth>=460?2:1);return grid;}
}
